<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap.php';
Auth::requireRole('admin');
$pdo=db(); $orderId=(int)($_GET['id']??0); $error=flash('error'); $success=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf($_POST['_csrf']??null); $to=trim((string)($_POST['status']??'')); $note=trim((string)($_POST['note']??''));
 $allowed=['paid','processing','shipped','completed','cancelled','refunded'];
 try{if(!in_array($to,$allowed,true))throw new RuntimeException('Invalid order status.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT status FROM orders WHERE id=? FOR UPDATE');$q->execute([$orderId]);$old=$q->fetchColumn();if($old===false)throw new RuntimeException('Order not found.');$pdo->prepare('UPDATE orders SET status=?,updated_at=NOW(),paid_at=CASE WHEN ?="paid" AND paid_at IS NULL THEN NOW() ELSE paid_at END WHERE id=?')->execute([$to,$to,$orderId]);if(in_array($to,['cancelled','refunded'],true))$pdo->prepare('UPDATE order_items SET fulfillment_status="cancelled",updated_at=NOW() WHERE order_id=?')->execute([$orderId]);OrderManager::addHistory($orderId,(int)Auth::userId(),(string)$old,$to,$note!==''?$note:'Admin status update.');$pdo->commit();flash('success','Order status updated.');redirect('/admin/order.php?id='.$orderId);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=APP_ENV==='development'?$e->getMessage():'Unable to update order.';}
}
$stmt=$pdo->prepare('SELECT o.*,u.name customer_name,u.email customer_email,u.phone customer_phone FROM orders o INNER JOIN users u ON u.id=o.customer_id WHERE o.id=? LIMIT 1');$stmt->execute([$orderId]);$order=$stmt->fetch();if(!$order){http_response_code(404);exit('Order not found.');}
$stmt=$pdo->prepare('SELECT oi.*,p.name,sp.business_name,sp.seller_code FROM order_items oi INNER JOIN products p ON p.id=oi.product_id LEFT JOIN seller_profiles sp ON sp.user_id=oi.seller_id WHERE oi.order_id=? ORDER BY oi.id');$stmt->execute([$orderId]);$items=$stmt->fetchAll();$h=$pdo->prepare('SELECT h.*,u.name actor_name FROM order_status_history h LEFT JOIN users u ON u.id=h.actor_user_id WHERE h.order_id=? ORDER BY h.id DESC');$h->execute([$orderId]);$history=$h->fetchAll();$shipping=json_decode((string)($order['shipping_address']??''),true)?:[];
function adminOrderBadge(string $s):string{return match($s){'completed'=>'success','cancelled','refunded'=>'danger','shipped'=>'info',default=>'warning'};}
?>
<!doctype html><html lang="en"><head><link rel="icon" href="<?= e(url('/assets/images/favicon-32.png')) ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e((string)$order['order_number'])?> · Admin</title><?php require __DIR__ . '/../partials/tailwind.php'; ?></head><body class="admin-shell"><?php require __DIR__.'/../partials/admin_sidebar.php';?><section class="admin-main"><?php require __DIR__.'/../partials/admin_topbar.php';?><main class="admin-content"><a href="<?=e(url('/admin/orders.php'))?>" style="color:#0088EE;font-weight:800;text-decoration:none">← Back to orders</a><div class="page-heading" style="margin-top:12px"><div><h1><?=e((string)$order['order_number'])?></h1><p>Customer: <?=e((string)$order['customer_name'])?> · <?=e((string)$order['customer_email'])?></p></div><span class="badge-df <?=e(adminOrderBadge((string)$order['status']))?>"><?=e(ucwords(str_replace('_',' ',(string)$order['status'])))?></span></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="checkout-grid"><section class="panel-df"><h2>Order items</h2><?php foreach($items as $i):?><div style="padding:15px 0;border-bottom:1px solid #E2E8F0"><strong><?=e((string)$i['name'])?></strong><div style="color:#64748B">Seller: <?=e((string)($i['business_name']??'Unknown'))?> · Qty <?= (int)$i['quantity']?> · GH₵ <?=number_format((float)$i['subtotal'],2)?></div><span class="badge-df <?=e(adminOrderBadge((string)$i['fulfillment_status']))?>"><?=e(ucwords(str_replace('_',' ',(string)$i['fulfillment_status'])))?></span></div><?php endforeach;?><div class="checkout-total"><strong>Total</strong><strong style="color:#0088EE">GH₵ <?=number_format((float)$order['total'],2)?></strong></div></section><aside><div class="panel-df"><h2>Admin status control</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label class="checkout-label">Status</label><select class="checkout-input" name="status"><?php foreach(['paid','processing','shipped','completed','cancelled','refunded'] as $s):?><option value="<?=e($s)?>" <?=((string)$order['status']===$s?'selected':'')?>><?=e(ucwords($s))?></option><?php endforeach;?></select><label class="checkout-label" style="display:block;margin-top:12px">Note</label><textarea class="checkout-input" name="note" rows="3" placeholder="Reason or internal note"></textarea><button class="btn btn-primary" style="margin-top:14px" type="submit">Save status</button></form></div><div class="panel-df" style="margin-top:18px"><h2>Delivery</h2><p><?=e((string)($shipping['full_name']??''))?><br><?=e((string)($shipping['phone']??''))?><br><?=e((string)($shipping['address']??''))?><br><?=e((string)($shipping['city']??''))?>, <?=e((string)($shipping['region']??''))?></p></div></aside></div><section class="panel-df" style="margin-top:18px"><h2>Status history</h2><?php foreach($history as $x):?><div style="padding:10px 0;border-bottom:1px solid #E2E8F0"><strong><?=e(ucwords(str_replace('_',' ',(string)$x['to_status'])))?></strong><span style="color:#64748B;font-size:.82rem"> · <?=e(date('d M Y · H:i',strtotime((string)$x['created_at'])))?><?php if($x['actor_name']):?> · <?=e((string)$x['actor_name'])?><?php endif;?></span><?php if($x['note']):?><div style="color:#64748B;margin-top:4px"><?=e((string)$x['note'])?></div><?php endif;?></div><?php endforeach;?></section></main></section></body></html>
